'use strict';

import utils from '../utils.js';
import stream from 'stream';

const CRLF = '\r\n';
const CRLF_BUFFER = Buffer.from(CRLF);
const BOUNDARY_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

function generateBoundary() {
  let boundary = '';

  while (boundary.length < 25) {
    boundary += BOUNDARY_CHARS[Math.floor(Math.random() * BOUNDARY_CHARS.length)];
  }

  return `axios-${boundary}`;
}

function escapeHeaderValue(value) {
  return String(value).replace(/[\r\n"]/g, char => {
    return char === '\r' ? '%0D' : char === '\n' ? '%0A' : '%22';
  });
}

function formDataToStream(form, headersHandler, options = {}) {
  const boundary = options.boundary || generateBoundary();

  if (boundary.length > 70 || !/^[\w'()+_,./:=?-]+$/.test(boundary)) {
    throw new Error('Invalid boundary');
  }

  const parts = [];
  let contentLength = 0;

  for (const [name, value] of form.entries()) {
    let headers = `--${boundary}${CRLF}Content-Disposition: form-data; name="${escapeHeaderValue(name)}"`;
    let size;

    if (utils.isString(value)) {
      size = Buffer.byteLength(value);
    } else {
      const filename = value.name || 'blob';
      headers += `; filename="${escapeHeaderValue(filename)}"${CRLF}Content-Type: ${value.type || 'application/octet-stream'}`;
      size = value.size;
    }

    headers += `${CRLF}${CRLF}`;
    const header = Buffer.from(headers);
    const ending = CRLF_BUFFER;
    contentLength += header.length + size + ending.length;
    parts.push({header, value, ending});
  }

  const footer = Buffer.from(`--${boundary}--${CRLF}`);
  contentLength += footer.length;

  headersHandler && headersHandler({
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
    'Content-Length': contentLength
  });

  return stream.Readable.from((async function* () {
    for (const part of parts) {
      yield part.header;

      if (utils.isString(part.value)) {
        yield Buffer.from(part.value);
      } else {
        for await (const chunk of part.value.stream()) {
          yield chunk;
        }
      }

      yield part.ending;
    }

    yield footer;
  })());
}

export default formDataToStream;
